def is_valid_ipv4(s: str) -> bool:
    """
    Check if a string is a valid IPv4 address.

    Args:
        s: The string to check.

    Returns:
        True if the string is a valid IPv4 address, False otherwise.
    """
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        try:
            num = int(part)
            if num < 0 or num > 255:
                return False
        except ValueError:
            return False
    return True
```

